function courseState(){return JSON.parse(localStorage.getItem('aft_course')||'{}')}
function setCourseState(x){localStorage.setItem('aft_course',JSON.stringify({...courseState(),...x}))}
function mainProgress(){const s=JSON.parse(localStorage.getItem('aft100')||'{"done":[]}');return s.done||[]}
function isCompleted(id){return mainProgress().includes(id)}
function render(){const id=requested();current=COURSES[id];if(!current){renderPending(id);return}document.title=current.title+' · Anästhesie Facharzt Trainer';$('#coursePhase').textContent=current.phase;$('#courseTitle').textContent=current.title;$('#courseIntro').textContent=current.intro;$('#courseTags').innerHTML=current.sources.map(x=>`<span class="tag">${esc(x)}</span>`).join('');$('#courseStatus').textContent=isCompleted(id)?'✓ Im 0→100-Pfad abgeschlossen':'Vollkurs · noch nicht abgeschlossen';$('#courseContent').innerHTML=current.sections.map((s,i)=>`<section class="section" id="${s.id}" data-section="${s.id}"><div class="eyebrow">KAPITEL ${i+1}/${current.sections.length}</div><h2>${s.title}</h2>${s.html}</section>`).join('');$('#toc').innerHTML=current.sections.map((s,i)=>`<button onclick="goSection('${s.id}')">${i+1}. ${s.title.replace(/^\d+\.\s*/, '')}</button>`).join('')+`<button onclick="goSection('quizSection')">✓ Selbsttest</button>`;renderQuiz();$('#quizSection').style.display='block';$('#finish').style.display='flex';$('#completeBtn').textContent=isCompleted(id)?'✓ Bereits abgeschlossen':'✓ Lektion abschließen';setupObserver();updateRead();updateNav()}
function renderPending(id){const title=id.replace(/[-_]/g,' ');$('#coursePhase').textContent='KURS IM AUFBAU';$('#courseTitle').textContent=title.charAt(0).toUpperCase()+title.slice(1);$('#courseIntro').textContent='Diese Einheit ist im 0→100-Fahrplan angelegt, aber der vollständige Quellenkurs ist noch nicht freigegeben.';$('#courseTags').innerHTML='<span class="tag">Nicht als gelernt markieren</span>';$('#toc').innerHTML='';$('#courseContent').innerHTML=`<div class="empty"><h2>Dieser Vollkurs wird noch aufgebaut.</h2><p>Ich zeige hier absichtlich keine dünne Stichwortliste mehr. Erst wenn die Lerneinheit als echter Kurs mit Erklärung, Prüfungsfragen und Quellenabgleich vorliegt, wird sie freigegeben.</p><a class="btn primary" href="lernplan.html">← Zum 0→100 Lernpfad</a></div>`;$('#quizSection').style.display='none';$('#finish').style.display='none';updateNav()}
function renderQuiz(){answers={};$('#quiz').innerHTML=current.quiz.map((q,qi)=>`<div class="qcard" id="q-${qi}"><strong>${qi+1}. ${q.q}</strong><div class="answers">${q.a.map((a,ai)=>`<button class="answer" onclick="answer(${qi},${ai},this)">${esc(a)}</button>`).join('')}</div><div class="feedback" id="fb-${qi}"></div></div>`).join('')}
function answer(qi,ai,btn){if(answers[qi]!=null)return;answers[qi]=ai;const q=current.quiz[qi],box=$('#q-'+qi),buttons=[...box.querySelectorAll('.answer')];buttons.forEach((b,i)=>{b.disabled=true;if(i===q.c)b.classList.add('good');if(i===ai&&i!==q.c)b.classList.add('bad')});$('#fb-'+qi).innerHTML=`<strong>${ai===q.c?'Richtig.':'Nicht ganz.'}</strong> ${q.e}`;updateRead()}
function updateRead(){if(!current)return;const seen=(courseState()[requested()]||{}).seen||[];const quizDone=Object.keys(answers).length;const total=current.sections.length+current.quiz.length;const value=Math.round((Math.min(current.sections.length,seen.length)+quizDone)/total*100);$('#readPct').textContent=value+'%';$('#readBar').style.width=value+'%';if(value===100)$('#finishText').textContent='Alle Abschnitte wurden besucht und alle Quizfragen beantwortet. Wenn du die Kernaussagen frei erklären kannst, schließe die Lektion ab.'}
function goSection(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:'smooth',block:'start'})}
function setupObserver(){const obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){const id=requested(),st=courseState(),cs=st[id]||{seen:[]};if(!cs.seen.includes(e.target.dataset.section)){cs.seen.push(e.target.dataset.section);st[id]=cs;localStorage.setItem('aft_course',JSON.stringify(st));updateRead()}}})},{threshold:.35});document.querySelectorAll('[data-section]').forEach(x=>obs.observe(x))}
function completeLesson(){if(!current)return;const id=requested(),s=JSON.parse(localStorage.getItem('aft100')||'{"done":[]}');s.done=s.done||[];if(!s.done.includes(id))s.done.push(id);localStorage.setItem('aft100',JSON.stringify(s));$('#completeBtn').textContent='✓ Abgeschlossen';$('#courseStatus').textContent='✓ Im 0→100-Pfad abgeschlossen';toast('Lektion im 0→100-Pfad abgeschlossen');setTimeout(()=>navigateCourse(1),700)}
function navigateCourse(dir){const id=requested(),i=COURSE_ORDER.indexOf(id),next=COURSE_ORDER[Math.max(0,Math.min(COURSE_ORDER.length-1,i+dir))];if(next&&next!==id)location.href='kurs.html?lesson='+encodeURIComponent(next)}
function updateNav(){const id=requested(),i=COURSE_ORDER.indexOf(id);$('#prevBtn').disabled=i<=0;$('#nextBtn').disabled=i<0||i>=COURSE_ORDER.length-1}
function toast(t){const n=document.createElement('div');n.style.cssText='position:fixed;right:18px;bottom:18px;background:#0f172a;color:#fff;padding:11px 14px;border-radius:12px;z-index:100;box-shadow:0 14px 40px rgba(0,0,0,.2)';n.textContent=t;document.body.appendChild(n);setTimeout(()=>n.remove(),1800)}
window.addEventListener('DOMContentLoaded',render);